 {float m=0;for(int j=0;j<D;j++)m+=x[j];printf("final: mean=%.4f first4=%.4f %.4f %.4f %.4f\n",m/D,x[0],x[1],x[2],x[3]);}
 float xn[D];ln(xn,x,lg,lb);
 {float m=0;for(int j=0;j<D;j++)m+=xn[j];printf("lnf: mean=%.4f first4=%.4f %.4f %.4f %.4f\n",m/D,xn[0],xn[1],xn[2],xn[3]);}
 float scores[V];for(int j=0;j<V;j++){float s=0;for(int d=0;d<D;d++)s+=xn[d]*we[j*D+d];scores[j]=s;}
 for(int t=0;t<10;t++){int best=0;float mx=-1e9f;for(int j=0;j<V;j++)if(scores[j]>mx){mx=scores[j];best=j;}printf("logit %d: token %d score %.4f\n",t,best,mx);scores[best]=-1e9f;}
